CREATE TABLE IF NOT EXISTS system_decision_options (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,decision_id UUID NOT NULL,title TEXT NOT NULL,evidence JSONB NOT NULL DEFAULT '{}'::jsonb,impact JSONB NOT NULL DEFAULT '{}'::jsonb,risk JSONB NOT NULL DEFAULT '{}'::jsonb,status TEXT NOT NULL DEFAULT 'candidate',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS system_decisions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',context JSONB NOT NULL DEFAULT '{}'::jsonb,selected_option_id UUID,approval_required BOOLEAN DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS system_decision_outcomes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,decision_id UUID NOT NULL,outcome JSONB NOT NULL DEFAULT '{}'::jsonb,measured_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_decisions_user ON system_decisions(user_id,status);
CREATE INDEX IF NOT EXISTS idx_options_user ON system_decision_options(user_id,decision_id);